import re
src = open('/workspace/v4/kernel.cu').read()

old_atv = '''    /* @V: each lane owns 4 contiguous output cols (c_out_base = k*4). */
    const int c_out_base = k * OUTS_PER_LANE;
    const int vd = 4 * ROWS_PER_WARP;
    #pragma unroll
    for (int c = 0; c < OUTS_PER_LANE; c++) {
        int c_out = c_out_base + c;
        float acc_v = 0.0f;
        #pragma unroll
        for (int j = 0; j < SEQ; j++)
            acc_v += at_vals[j] * __half2float(sV[j * DIM + c_out]);
        sQ[row * DIM + c_out] = __float2half_rn(acc_v);
    }'''

new_atv = '''    /* @V: each lane owns OUTS_PER_LANE=4 contiguous output cols. Vectorized via half2:
       2 pairs of consecutive c_out cols processed at a time using __hfma2.
       Accumulator is fp16 to match storage; only need final fp16 precision. */
    const int c_out_base = k * OUTS_PER_LANE;
    __half2 acc_out[OUTS_PER_LANE / 2];
    #pragma unroll
    for (int c2 = 0; c2 < OUTS_PER_LANE / 2; c2++)
        acc_out[c2] = __float2half2_rn(0.0f);
    #pragma unroll
    for (int j = 0; j < SEQ; j++) {
        __half a_h = __float2half_rn(at_vals[j]);
        __half2 a_h2 = __half2half2(a_h);
        #pragma unroll
        for (int c2 = 0; c2 < OUTS_PER_LANE / 2; c2++) {
            int c_out = c_out_base + c2 * 2;
            __half2 v_pair = __halves2half2(sV[j * DIM + c_out], sV[j * DIM + c_out + 1]);
            acc_out[c2] = __hfma2(a_h2, v_pair, acc_out[c2]);
        }
    }
    #pragma unroll
    for (int c2 = 0; c2 < OUTS_PER_LANE / 2; c2++) {
        int c_out = c_out_base + c2 * 2;
        *(__half2*)&sQ[row * DIM + c_out] = acc_out[c2];
    }'''

if old_atv in src:
    src = src.replace(old_atv, new_atv)
    open('/workspace/v4/kernel.cu', 'w').write(src)
    print("patch applied")
else:
    print("ERROR: did not find the @V section to replace")
    import sys; sys.exit(1)
